# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: fraud_service/app/rules/velocity.py

from datetime import datetime, timedelta
from sqlalchemy.orm import Session
from fraud_service.app.models.fraud import FraudCheck
from fraud_service.app.schemas.fraud import RuleResult
from fraud_service.app.config import settings


class VelocityRules:

    def check_card_velocity(self, db: Session, card_fingerprint: str) -> RuleResult:
        window = settings.card_velocity_window_minutes
        since = datetime.utcnow() - timedelta(minutes=window)
        count = (
            db.query(FraudCheck)
            .filter(
                FraudCheck.card_fingerprint == card_fingerprint,
                FraudCheck.created_at >= since,
            )
            .count()
        )

        max_attempts = settings.card_velocity_max_attempts

        if count >= max_attempts:
            return RuleResult(
                rule_name="card_velocity_high",
                triggered=True,
                score_impact=40,
                reason=f"Card used {count} times in {window} minutes"
            )
        if count >= max(2, max_attempts - 2):
            return RuleResult(
                rule_name="card_velocity_medium",
                triggered=True,
                score_impact=15,
                reason=f"Card used {count} times in {window} minutes"
            )
        return RuleResult(rule_name="card_velocity", triggered=False, score_impact=0)

    def check_ip_velocity(self, db: Session, ip_address: str) -> RuleResult:
        if not ip_address:
            return RuleResult(rule_name="ip_velocity", triggered=False, score_impact=0)

        window = settings.ip_velocity_window_minutes
        since = datetime.utcnow() - timedelta(minutes=window)
        count = (
            db.query(FraudCheck)
            .filter(
                FraudCheck.ip_address == ip_address,
                FraudCheck.created_at >= since,
            )
            .count()
        )

        if count >= settings.ip_velocity_max_attempts:
            return RuleResult(
                rule_name="ip_velocity_high",
                triggered=True,
                score_impact=35,
                reason=f"IP made {count} attempts in {window} minutes"
            )
        return RuleResult(rule_name="ip_velocity", triggered=False, score_impact=0)

    def check_customer_velocity(self, db: Session, customer_id: str) -> RuleResult:
        window_hours = settings.customer_velocity_window_hours
        since = datetime.utcnow() - timedelta(hours=window_hours)
        count = (
            db.query(FraudCheck)
            .filter(
                FraudCheck.customer_id == customer_id,
                FraudCheck.created_at >= since,
            )
            .count()
        )

        if count >= settings.customer_velocity_max_attempts:
            return RuleResult(
                rule_name="customer_velocity_high",
                triggered=True,
                score_impact=25,
                reason=f"Customer made {count} purchases in {window_hours} hours"
            )
        return RuleResult(rule_name="customer_velocity", triggered=False, score_impact=0)

    def get_counts_for_ml(self, db: Session, card_fingerprint: str, ip: str, customer_id: str) -> dict:
        """Returns velocity counts used as ML features"""
        since_1h = datetime.utcnow() - timedelta(hours=1)
        card_count = db.query(FraudCheck).filter(
            FraudCheck.card_fingerprint == card_fingerprint,
            FraudCheck.created_at >= since_1h
        ).count()
        ip_count = db.query(FraudCheck).filter(
            FraudCheck.ip_address == ip,
            FraudCheck.created_at >= since_1h
        ).count() if ip else 0
        customer_total = db.query(FraudCheck).filter(
            FraudCheck.customer_id == customer_id
        ).count()
        customer_failed = db.query(FraudCheck).filter(
            FraudCheck.customer_id == customer_id,
            FraudCheck.allowed == False
        ).count()
        return {
            "card_velocity_1h": card_count,
            "ip_velocity_1h": ip_count,
            "customer_tx_count": customer_total,
            "customer_failed_count": customer_failed,
        }
